async function securityLogsPage(){
 const content=$('.cs-content');if(!content)return;const existing=content.querySelector('#security-log-root');if(existing)return;
 const status=$('#page-status');const wrap=document.createElement('section');wrap.id='security-log-root';wrap.innerHTML=`<section class="cs-hero"><div><div class="cs-eyebrow">School safety oversight</div><h2>Student entry & exit register</h2><p>Review gate activity and school safety statistics. This report is read-only; only Security staff can record entries and exits.</p></div><span class="cs-pill blue">Read-only</span></section><section class="cs-stats" id="cs-gate-stats"><article class="cs-stat"><div class="cs-stat-label">Records loaded</div><div class="cs-stat-value">—</div></article><article class="cs-stat"><div class="cs-stat-label">Entries today</div><div class="cs-stat-value">—</div></article><article class="cs-stat"><div class="cs-stat-label">Exits today</div><div class="cs-stat-value">—</div></article><article class="cs-stat"><div class="cs-stat-label">Students represented</div><div class="cs-stat-value">—</div></article></section><section class="cs-panel"><div class="cs-toolbar"><input class="cs-search" id="cs-gate-search" placeholder="Search student, admission number or responsible person…"><select id="cs-gate-type" class="cs-search" aria-label="Filter by event type"><option value="">All events</option><option value="ENTRY">Entries</option><option value="EXIT">Exits</option></select><button type="button" class="cs-btn secondary" id="cs-gate-refresh">Refresh report</button></div><div class="cs-table-wrap"><table class="cs-table"><thead><tr><th>Date & time</th><th>Student</th><th>Admission no.</th><th>Class</th><th>Event</th><th>Responsible person / transport</th><th>Recorded by</th><th>Notes</th></tr></thead><tbody id="cs-gate-rows"><tr><td colspan="8">Loading gate logs…</td></tr></tbody></table></div><p class="cs-footnote">School-wide report. No create, edit or delete actions are available to Head Teacher or Administrator.</p></section>`;
 const hero=content.querySelector('.cs-hero');if(hero)hero.remove();content.insertBefore(wrap,content.querySelector('#page-status')||null);
 let logs=[];const tbody=$('#cs-gate-rows');function render(){const q=($('#cs-gate-search').value||'').toLowerCase().trim(),type=$('#cs-gate-type').value;const rows=logs.filter(l=>{const s=l.student||{},who=l.handlerName||'',recorded=l.recordedBy||{};return(!type||l.eventType===type)&&(!q||`${s.firstName||''} ${s.lastName||''} ${s.admissionNumber||''} ${s.classLevel||''} ${who} ${recorded.firstName||''} ${recorded.lastName||''}`.toLowerCase().includes(q))});tbody.innerHTML=rows.length?rows.map(l=>{const st=l.student||{},rb=l.recordedBy||{};return `<tr><td>${esc(new Date(l.occurredAt).toLocaleString())}</td><td>${esc([st.firstName,st.lastName].filter(Boolean).join(' ')||'Unknown student')}</td><td>${esc(st.admissionNumber||'—')}</td><td>${esc(st.classLevel||'—')}</td><td><span class="cs-pill ${l.eventType==='ENTRY'?'green':'orange'}">${esc(l.eventType||'—')}</span></td><td>${esc(l.handlerName||String(l.handlerType||'').replaceAll('_',' ')||'—')}${l.handlerPhone?`<div class="cs-person-meta">${esc(l.handlerPhone)}</div>`:''}</td><td>${esc([rb.firstName,rb.lastName].filter(Boolean).join(' ')||rb.email||'—')}</td><td>${esc(l.notes||'—')}</td></tr>`}).join(''):'<tr><td colspan="8">No gate records match this filter.</td></tr>'}
 async function load(){try{const d=await api('/api/security-portal/gate-logs');logs=Array.isArray(d.logs)?d.logs:[];const now=new Date(),today=logs.filter(l=>{const t=new Date(l.occurredAt);return t.getFullYear()===now.getFullYear()&&t.getMonth()===now.getMonth()&&t.getDate()===now.getDate()});const entries=today.filter(l=>l.eventType==='ENTRY').length,exits=today.filter(l=>l.eventType==='EXIT').length,students=new Set(logs.map(l=>l.studentId).filter(Boolean)).size;$('#cs-gate-stats').innerHTML=[['Records loaded',logs.length],['Entries today',entries],['Exits today',exits],['Students represented',students]].map(([label,value])=>`<article class="cs-stat"><div class="cs-stat-label">${label}</div><div class="cs-stat-value">${Number(value).toLocaleString()}</div></article>`).join('');render();if(status)status.textContent='Read-only gate report loaded.'}catch(e){tbody.innerHTML=`<tr><td colspan="8">${esc(e.message||'Could not load gate logs.')}</td></tr>`;if(status)status.textContent=e.message||'Could not load gate logs.';throw e}}
 $('#cs-gate-search').addEventListener('input',render);$('#cs-gate-type').addEventListener('change',render);$('#cs-gate-refresh').addEventListener('click',()=>load().catch(()=>{}));await load()
}
async function notificationsPage(){
 const list=$('#notification-list');
 function renderRows(rows){
  state.notifications=rows;
  const unread=rows.filter(x=>!(x.readAt||x.read===true||String(x.status||'').toUpperCase()==='READ')).length;
  if($('#notifications-count'))$('#notifications-count').textContent=String(unread);
  setUnreadCount(unread);
  try{sessionStorage.setItem(notificationsCacheKey(),JSON.stringify({rows,at:Date.now()}))}catch(e){}
  if(list)list.innerHTML=rows.length?rows.map(n=>`<article class="cs-list-item ${n.readAt?'':'unread'}"><div class="cs-list-icon">${n.type==='ANNOUNCEMENT'?'▤':n.type==='MESSAGE'?'✉':'♧'}</div><div class="cs-list-copy"><div class="cs-list-title">${esc(n.title)}</div><div class="cs-list-content">${esc(n.content)}</div><div class="cs-list-meta">${date(n.createdAt)} · ${n.readAt?'Read':'Unread'}</div></div><div class="cs-list-actions">${!n.readAt?`<button class="cs-btn secondary small" data-read="${esc(n.id)}" type="button">Mark read</button>`:''}${n.targetUrl?`<button class="cs-btn soft small" data-open="${esc(n.id)}" data-url="${esc(n.targetUrl)}" type="button">Open</button>`:''}</div></article>`).join(''):empty('You are all caught up','Important school updates will appear here.');
  $$('[data-read]').forEach(btn=>btn.addEventListener('click',async()=>{try{await markRead(btn.dataset.read);await draw(true);await refreshUnreadBadges()}catch(e){toast(e.message,true)}}));
  $$('[data-open]').forEach(btn=>btn.addEventListener('click',async()=>{try{const item=state.notifications.find(n=>String(n.id)===String(btn.dataset.open));if(item&&!item.readAt){await markRead(item.id);await refreshUnreadBadges()}const target=btn.dataset.url;if(target)location.href=target;else{await draw(true);toast('This notification has no destination page.')}}catch(e){toast(e.message,true)}}));
 }
 async function draw(skipCache=false){
  let cached=null;
  if(!skipCache){try{const c=JSON.parse(sessionStorage.getItem(notificationsCacheKey())||'null');if(c&&Array.isArray(c.rows)&&Date.now()-c.at<120000)cached=c.rows}catch(e){}}
  if(cached)renderRows(cached);
  try{const payload=await api('/api/owner-workspace/notifications');const rows=Array.isArray(payload)?payload:(Array.isArray(payload.notifications)?payload.notifications:Array.isArray(payload.data)?payload.data:[]);renderRows(rows)}
  catch(e){if(!cached){if(list)list.innerHTML=empty('Notifications could not be loaded',e.message||'Check your connection and refresh.');throw e}}
 }
 async function markRead(id){await api('/api/owner-workspace/notifications/'+encodeURIComponent(id)+'/read',{method:'PATCH',body:'{}'});const item=state.notifications.find(n=>String(n.id)===String(id));if(item&&!item.readAt)item.readAt=new Date().toISOString()}
 async function refreshUnreadBadges(){await refreshUnread(true,state.notifications);if(window.ConnectSukuuRoleShell&&typeof window.ConnectSukuuRoleShell.refreshUnread==='function')await window.ConnectSukuuRoleShell.refreshUnread()}
 $('#notifications-mark-all')?.addEventListener('click',async()=>{try{const payload=await api('/api/owner-workspace/notifications');const rows=Array.isArray(payload)?payload:(Array.isArray(payload.notifications)?payload.notifications:Array.isArray(payload.data)?payload.data:[]);const pending=rows.filter(n=>!(n.readAt||n.read===true||String(n.status||'').toUpperCase()==='READ'));await Promise.all(pending.map(n=>markRead(n.id)));toast('Notifications marked as read.');await draw(true);await refreshUnreadBadges()}catch(e){toast(e.message,true)}});
 await draw();
}
async function supportPage(){const form=$('#support-form'),list=$('#support-list'),file=$('#support-attachment'),fileLabel=$('#support-attachment-label');file?.addEventListener('change',()=>{if(fileLabel)fileLabel.textContent=file.files?.[0]?.name||'No file selected'});async function draw(){const rows=await api('/api/owner-workspace/support');if(list)list.innerHTML=rows.length?rows.map(t=>`<article class="cs-list-item"><div class="cs-list-icon">⚑</div><div class="cs-list-copy"><div class="cs-list-title">${esc(t.subject)} <span class="cs-pill ${t.status==='OPEN'?'orange':'green'}">${esc(t.status)}</span></div><div class="cs-list-content">${esc(t.content)}</div><div class="cs-list-meta">${esc(t.category)} · ${date(t.createdAt)}${t.attachmentName?' · Attachment: '+esc(t.attachmentName):''}</div></div>${t.attachmentName?`<button class="cs-btn secondary small" data-download-ticket="${esc(t.id)}" data-download-name="${esc(t.attachmentName)}">Download</button>`:''}</article>`).join(''):empty('No support requests','Report an issue and its status will appear here.');$$('[data-download-ticket]').forEach(btn=>btn.addEventListener('click',async()=>{try{const token=localStorage.getItem('cs_token')||localStorage.getItem('connectsukuu_token')||'';const r=await fetch(apiBase()+'/api/owner-workspace/support/'+encodeURIComponent(btn.dataset.downloadTicket)+'/attachment',{headers:{Authorization:'Bearer '+token}});if(!r.ok){const err=await r.json().catch(()=>({}));throw Error(err.error||'Download failed')}const blob=await r.blob();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=btn.dataset.downloadName||'support-attachment';a.click();URL.revokeObjectURL(url)}catch(e){toast(e.message,true)}}))}if(form)form.addEventListener('submit',async e=>{e.preventDefault();try{const payload=new FormData();payload.append('category',form.elements.category.value);payload.append('subject',form.elements.subject.value);payload.append('content',form.elements.content.value);if(file?.files?.[0])payload.append('attachment',file.files[0]);await api('/api/owner-workspace/support',{method:'POST',body:payload});toast('Support request submitted.');form.reset();if(fileLabel)fileLabel.textContent='No file selected';await draw()}catch(err){toast(err.message,true)}});await draw()}

async function refreshOwnerIdentity(){try{const result=await api('/api/auth/profile');const profile=result.user||result;const current=user()||{};const merged={...current,...profile};localStorage.setItem('cs_user',JSON.stringify(merged));localStorage.setItem('connectsukuu_user',JSON.stringify(merged));const name=[profile.firstName,profile.lastName].filter(Boolean).join(' ')||profile.email||'School Owner';const nameEl=$('#cs-profile-name');if(nameEl)nameEl.textContent=name;const avatar=$('#cs-profile-avatar');if(avatar){avatar.textContent=initials(name);if(profile.photoUrl){const token=localStorage.getItem('cs_token')||localStorage.getItem('connectsukuu_token')||'';const response=await fetch(apiBase()+'/api/auth/profile/photo',{headers:{Authorization:'Bearer '+token}});if(response.ok){const blob=await response.blob();const url=URL.createObjectURL(blob);avatar.innerHTML='';const img=document.createElement('img');img.className='cs-profile-photo';img.alt='Profile photo';img.src=url;avatar.appendChild(img);}}}return profile}catch(_){return user()||{}}}
